 facts.append({'id':pid.replace('oriental_mindoro_','')+'_discovery_11','placeID':pid,'suggestedMission':11,'title':'Living heritage and practical skills','category':'living_heritage','text':text,'sourceIDs':sources,'evidenceStatus':'attributed_research_summary','question':'Which cultural theme or practical skill is named in this briefing?','answer':theme,'options':[theme,'A tradition shared identically by every resident','A proven single discoverer of the municipality','Permission to reproduce every local design']})
 facts.append({'id':pid.replace('oriental_mindoro_','')+'_discovery_12','placeID':pid,'suggestedMission':12,'title':'Identity and traveler values','category':'identity_and_values','text':name+': '+text+' In this adventure, practice these traveler values: '+ '; '.join(values)+'. These are learning goals, not a claim that all residents hold identical values.','sourceIDs':sources,'evidenceStatus':'attributed_research_summary','question':'How should your traveler care for this heritage and identity?','answer':'Respect attribution, community differences, and appropriate permissions','options':['Respect attribution, community differences, and appropriate permissions','Treat every resident as following the same practice','Take real cultural objects as collectibles','Copy expressive material without checking permission']})
